  out.rate = dv.getFloat32(off + 4, true)
  out.t_sim_ns = dv.getUint32(off + 8, true) + dv.getInt32(off + 12, true) * 4294967296
  out.t_srv_ns = dv.getUint32(off + 16, true) + dv.getInt32(off + 20, true) * 4294967296
